using System.Security.Claims; using System.Text; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using MaintenancePRO.Api.Security; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.RateLimiting; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens;
var b=WebApplication.CreateBuilder(args); b.Services.AddControllers(); b.Services.AddEndpointsApiExplorer(); b.Services.AddSwaggerGen(); b.Services.AddDbContext<AppDbContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("Default")));
b.Services.AddIdentityCore<ApplicationUser>(o=>{o.Password.RequiredLength=12;o.Password.RequireDigit=true;o.Password.RequireLowercase=true;o.Password.RequireUppercase=true;o.Password.RequireNonAlphanumeric=true;o.User.RequireUniqueEmail=true;o.Lockout.AllowedForNewUsers=true;o.Lockout.MaxFailedAccessAttempts=5;o.Lockout.DefaultLockoutTimeSpan=TimeSpan.FromMinutes(15);}).AddRoles<IdentityRole>().AddEntityFrameworkStores<AppDbContext>().AddSignInManager();
var jwtKey=b.Configuration["Jwt:Key"]; if(string.IsNullOrWhiteSpace(jwtKey)||Encoding.UTF8.GetByteCount(jwtKey)<32)throw new InvalidOperationException("Configure Jwt:Key via dotnet user-secrets ou variable d'environnement (minimum 32 octets).");
b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=b.Configuration["Jwt:Issuer"]??"MaintenancePRO",ValidateAudience=true,ValidAudience=b.Configuration["Jwt:Audience"]??"MaintenancePRO.Client",ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)),ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30)});
b.Services.AddAuthorization(o=>{o.AddPolicy("AdminOnly",p=>p.RequireRole(AppRoles.Admin));o.AddPolicy("ManageEquipment",p=>p.RequireRole(AppRoles.Admin,AppRoles.Supervisor));o.AddPolicy("WorkInterventions",p=>p.RequireRole(AppRoles.Admin,AppRoles.Supervisor,AppRoles.Technician));}); b.Services.AddScoped<TokenService>(); b.Services.AddRateLimiter(o=>{o.RejectionStatusCode=429;o.AddFixedWindowLimiter("auth",x=>{x.PermitLimit=8;x.Window=TimeSpan.FromMinutes(1);x.QueueLimit=0;});});
var app=b.Build(); using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();await db.Database.EnsureCreatedAsync();var rm=scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();foreach(var r in new[]{AppRoles.Admin,AppRoles.Supervisor,AppRoles.Technician,AppRoles.User})if(!await rm.RoleExistsAsync(r))await rm.CreateAsync(new IdentityRole(r));var email=app.Configuration["BootstrapAdmin:Email"];var password=app.Configuration["BootstrapAdmin:Password"];if(!string.IsNullOrWhiteSpace(email)&&!string.IsNullOrWhiteSpace(password)){var um=scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();if(await um.FindByEmailAsync(email)==null){var admin=new ApplicationUser{UserName=email,Email=email,EmailConfirmed=true,DisplayName="Administrateur",Status=AccountStatus.Active};var created=await um.CreateAsync(admin,password);if(created.Succeeded)await um.AddToRoleAsync(admin,AppRoles.Admin);else app.Logger.LogError("Bootstrap admin creation failed: {Errors}",string.Join(",",created.Errors.Select(e=>e.Code)));}}}
app.Use(async(ctx,next)=>{ctx.Response.Headers["X-Content-Type-Options"]="nosniff";ctx.Response.Headers["X-Frame-Options"]="DENY";ctx.Response.Headers["Referrer-Policy"]="no-referrer";ctx.Response.Headers["Cache-Control"]="no-store";await next();});if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}else app.UseHttpsRedirection();app.UseRateLimiter();app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run();
